script:
frappe.db.get_list('Employee', {
    filters: { user_id: frappe.session.user },
    fields: [
        'employee_name',
        'designation',
        'date_of_joining',
        'reports_to',
        'department',
        'image',
        'date_of_birth'
    ],
    limit: 1
}).then(async (employees) => {

    if (!employees.length){
        root_element.querySelector(".employee-card").innerHTML =
            "<div style='padding:20px'>No Employee linked to this user.</div>";
        return;
    }

    let emp = employees[0];

    let managerName = "-";

    if(emp.reports_to){
        const manager = await frappe.db.get_doc("Employee", emp.reports_to);
        managerName = manager.employee_name || emp.reports_to;
    }

    const formatDate = (date) => {
        if(!date) return "-";
        const d = new Date(date);
        const day = String(d.getDate()).padStart(2,'0');
        const month = String(d.getMonth()+1).padStart(2,'0');
        const year = d.getFullYear();
        return `${day}-${month}-${year}`;
    };

    const calcAge = (dob) => {
        if(!dob) return "-";
        let diff = Date.now() - new Date(dob).getTime();
        return Math.abs(new Date(diff).getUTCFullYear() - 1970);
    };

    const calcTenure = (joining) => {
        if(!joining) return "-";
        let diff = Date.now() - new Date(joining).getTime();
        return (diff / (1000 * 60 * 60 * 24 * 365)).toFixed(1) + " yrs";
    };

    root_element.querySelector("#emp-name").textContent = emp.employee_name || "-";
    root_element.querySelector("#emp-designation").textContent = emp.designation || "-";
    root_element.querySelector("#emp-joining").textContent = formatDate(emp.date_of_joining);
    root_element.querySelector("#emp-manager").textContent = managerName;
    root_element.querySelector("#emp-department").textContent = emp.department || "-";
    root_element.querySelector("#emp-dob").textContent = formatDate(emp.date_of_birth);
    root_element.querySelector("#emp-age").textContent = calcAge(emp.date_of_birth);
    root_element.querySelector("#emp-tenure").textContent = calcTenure(emp.date_of_joining);

    root_element.querySelector("#emp-image").src =
        emp.image || "/assets/frappe/images/default-avatar.png";

});

