style:
.team-card{
    background:white;
    border-radius:18px;
    padding:28px;
    box-shadow:0 6px 26px rgba(0,0,0,.04);
}

/* HEADER */

.team-header-row{
    display:flex;
    justify-content:space-between;
    align-items:center;
    margin-bottom:22px;
}

.team-header{
    font-size:19px;
    font-weight:600;
}

/* BUTTON */

.time-toggle{
    border:1px solid #e5e7eb;
    background:white;
    padding:6px 14px;
    border-radius:8px;
    font-size:13px;
    font-weight:600;
    cursor:pointer;
}

.time-toggle:hover{
    background:#f8fafc;
}

/* TODAY TABLE */

.team-table{
    width:100%;
    border-collapse:collapse;
}

.team-table th{
   text-align:center;
    font-size:13px;
    font-weight:600;
    color:#64748b;
    padding:12px;
    border-bottom:1px solid #e5e7eb;
}

.team-table td{
    padding:14px 12px;
    border-bottom:1px solid #f1f5f9;
}

.team-table tbody tr:hover{
    background:#fafafa;
}

/* EMPLOYEE CELL */

.emp-cell{
    display:flex;
    align-items:center;      /* vertical alignment */
    justify-content:center;  /* centers the whole block */
    gap:12px;
    text-align:left;         /* keeps text natural */
}

.emp-avatar{
    width:40px;
    height:40px;
    border-radius:50%;
    object-fit:cover;
}

.emp-name{
    font-weight:600;
}
.sticky-col{
    text-align:center;
}
.emp-sub{
    font-size:12px;
    color:#64748b;
}

/* BADGES */

.badge{
    padding:4px 10px;
    border-radius:999px;
    font-size:12px;
    font-weight:600;
}

.present{
    background:#ecfdf5;
    color:#065f46;
}

.late{
    background:#fffbeb;
    color:#92400e;
}

.leave{
    background:#eff6ff;
    color:#1e40af;
}

.missing{
    background:#fef2f2;
    color:#991b1b;
}

/* MATRIX */

.matrix-wrapper{
    overflow-x:auto;
}

.matrix-table{
    width:100%;
    border-collapse:collapse;
}

.matrix-table th{
    font-size:13px;
    font-weight:600;
    color:#64748b;
    padding:14px;
    border-bottom:1px solid #e5e7eb;
    background:white;
}

.matrix-table td{
    padding:16px 12px;
    text-align:center;
    border-bottom:1px solid #f1f5f9;
}

.matrix-table tbody tr:hover{
    background:#fafafa;
}

/* STATUS CELLS */

.matrix-table td.present{
    background:#f0fdf4;
    box-shadow: inset 4px 0 #22c55e;
}

.matrix-table td.late{
    background:#fffbeb;
    box-shadow: inset 4px 0 #f59e0b;
}

.matrix-table td.leave{
    background:#eff6ff;
    box-shadow: inset 4px 0 #3b82f6;
}

.matrix-table td.missing{
    background:#fef2f2;
    box-shadow: inset 4px 0 #ef4444;
}

/* STICKY */

.sticky-col{
    position:sticky;
    left:0;
    background:white;
    z-index:2;
    border-right:1px solid #f1f5f9;
}

/* TODAY COLUMN */

.matrix-table td:last-child,
.matrix-table th:last-child{
    background:#f8fafc;
}
.holiday{
    background:#ede9fe;
    color:#5b21b6;
}

.matrix-table td.holiday{
    background:#f5f3ff;
    box-shadow: inset 4px 0 #8b5cf6;
}
.team-table th,
.team-table td,
.matrix-table th,
.matrix-table td{
    text-align:center;
    vertical-align:middle;
}
